//! Parity: passlib-format password hashing in both directions, `valid_username`, and token API
//! keys (`fixtures/users.json`, generated by `fixtures/gen_users.py`).

mod common;

use std::io::Write;
use std::process::{Command, Stdio};

use meerschaum_core::Value;
use meerschaum_core::users::{
    Expiration, Token, ab64_decode, hash_password, valid_username, verify_password,
};

#[test]
fn python_hashes_verify_in_rust() {
    let fixture = common::load_fixture("users.json");
    let hashes = fixture.get("hashes").and_then(Value::as_list).unwrap();
    for h in hashes {
        let password = h.get("password").and_then(Value::as_str).unwrap();
        let hash = h.get("hash").and_then(Value::as_str).unwrap();
        assert!(
            verify_password(password, hash).unwrap(),
            "{password:?} should verify against {hash}"
        );
        let parts: Vec<&str> = hash.split('$').collect();
        let rounds: u32 = parts[2].parse().unwrap();
        if rounds > 100_000 {
            continue;
        }
        assert!(!verify_password(&format!("{password}x"), hash).unwrap());

        // With the same salt and rounds, Rust produces the identical string.
        let salt = ab64_decode(parts[3]).unwrap();
        assert_eq!(
            hash_password(password, Some(&salt), Some(rounds)).unwrap(),
            hash
        );
    }
}

#[test]
fn edge_cases_match_python() {
    let fixture = common::load_fixture("users.json");
    for (name, case) in fixture.get("edge_cases").and_then(Value::as_map).unwrap() {
        let hash = case.get("hash").and_then(Value::as_str).unwrap();
        let result = verify_password("pw", hash);
        match (result, case.get("ok")) {
            (Ok(v), Some(expected)) => assert_eq!(Some(v), expected.as_bool(), "{name}"),
            (Err(_), None) => {}
            (r, e) => panic!("{name}: {r:?} vs {e:?}"),
        }
    }
    for (name, ok) in fixture
        .get("valid_username")
        .and_then(Value::as_map)
        .unwrap()
    {
        assert_eq!(
            valid_username(name).success,
            ok.as_bool().unwrap(),
            "{name:?}"
        );
    }
    let api = fixture.get("api_key").unwrap();
    let mut token = Token::new(
        Some("device"),
        Expiration::Default,
        None,
        366,
        chrono::Utc::now(),
    );
    token.id = Some(uuid::Uuid::parse_str(api.get("id").and_then(Value::as_str).unwrap()).unwrap());
    token.secret = api.get("secret").and_then(Value::as_str).map(String::from);
    assert_eq!(
        Some(token.get_api_key().as_str()),
        api.get("key").and_then(Value::as_str)
    );
}

/// Rust-produced hashes must verify with the Python `verify_password`. Runs the Python side
/// with `PYTHONPATH` set to the repository root; skipped (with a message) when Python or the
/// package cannot be imported.
#[test]
fn rust_hashes_verify_in_python() {
    let passwords = ["hunter2", "", "pässwörd ✓", " spaces ", "emoji 🐍"];
    let mut cases = Vec::new();
    for p in passwords {
        cases.push((p.to_string(), hash_password(p, None, Some(1000)).unwrap()));
    }
    cases.push((
        "default-rounds".to_string(),
        hash_password("default-rounds", None, None).unwrap(),
    ));
    cases.push((
        "token-secret".to_string(),
        Token::hash_secret("token-secret").unwrap(),
    ));
    // A wrong password must not verify on the Python side either.
    cases.push(("wrong".to_string(), cases[0].1.clone()));

    let payload = Value::List(
        cases
            .iter()
            .map(|(p, h)| {
                let mut m = meerschaum_core::Map::new();
                m.insert("password".into(), Value::from(p.as_str()));
                m.insert("hash".into(), Value::from(h.as_str()));
                Value::Map(m)
            })
            .collect(),
    );
    let repo = common::repo_root();
    let script = common::fixtures().join("verify.py");
    let python = std::env::var("PYTHON").unwrap_or_else(|_| "python3".to_string());
    let child = Command::new(&python)
        .arg(&script)
        .current_dir(&repo)
        .env("PYTHONPATH", &repo)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn();
    let Ok(mut child) = child else {
        eprintln!("skipping: could not start {python}");
        return;
    };
    child
        .stdin
        .take()
        .unwrap()
        .write_all(payload.to_json_string().as_bytes())
        .unwrap();
    let output = child.wait_with_output().unwrap();
    if !output.status.success() {
        eprintln!("skipping: the Python side could not run (is meerschaum importable?)");
        return;
    }
    let text = String::from_utf8(output.stdout).unwrap();
    let results = Value::from_json_str(text.trim().lines().last().unwrap()).unwrap();
    let results: Vec<bool> = results
        .as_list()
        .unwrap()
        .iter()
        .map(|v| v.as_bool().unwrap())
        .collect();
    let mut expected = vec![true; cases.len()];
    *expected.last_mut().unwrap() = false;
    assert_eq!(results, expected, "Python verification of Rust hashes");
}
